# -*- coding: utf-8 -*-
# Corrige le theme/nom (annules par erreur d'ordre d'application) + ajoute la description de camp
# A lancer depuis la racine du dossier pompiers-app : python3 apply_update_5.py
import pathlib

FILES = {}

FILES['backend/prisma/schema.prisma'] = '// Schema Prisma - Application de suivi de camps d\'entrainement\n// Par defaut : SQLite (aucune installation requise).\n// Pour passer sur PostgreSQL en production, remplacer le provider ci-dessous\n// par "postgresql" et adapter DATABASE_URL dans .env\n\ngenerator client {\n  provider = "prisma-client-js"\n}\n\ndatasource db {\n  provider = "sqlite"\n  url      = env("DATABASE_URL")\n}\n\n// Note : pas d\'enum Prisma ici (ExerciseUnit / RecurrenceType) car SQLite ne supporte pas\n// les enums natifs. Les valeurs autorisees ("REPS"/"SECONDS", "DAILY"/"WEEKLY"/"EVERY_N_DAYS")\n// sont validees cote API avec zod.\n\nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  passwordHash   String\n  name           String\n  weightKg       Float?\n  heightCm       Float?\n  birthDate      DateTime?\n  sex            String?  // "F" | "M" | "AUTRE" | null, libre / optionnel\n  createdAt      DateTime @default(now())\n\n  memberships    CampMembership[]\n  createdCamps   Camp[]            @relation("CampCreator")\n  createdExos    Exercise[]        @relation("ExerciseCreator")\n  logs           ExerciseLog[]\n  subscriptions  PushSubscription[]\n  badges         UserBadge[]\n  campMessages   CampMessage[]\n  sentMessages   DirectMessage[]   @relation("MessageSender")\n  receivedMessages DirectMessage[] @relation("MessageRecipient")\n}\n\nmodel Exercise {\n  id          String       @id @default(cuid())\n  name        String\n  description String?\n  unit        String       // "REPS" ou "SECONDS"\n  isCustom    Boolean      @default(false)\n  createdById String?\n  createdBy   User?        @relation("ExerciseCreator", fields: [createdById], references: [id])\n  createdAt   DateTime     @default(now())\n\n  campExercises CampExercise[]\n  logs          ExerciseLog[]\n}\n\nmodel Camp {\n  id          String    @id @default(cuid())\n  name        String\n  description String?\n  code        String    @unique\n  createdById String\n  createdBy   User      @relation("CampCreator", fields: [createdById], references: [id])\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime  @default(now())\n\n  exercises CampExercise[]\n  members   CampMembership[]\n  logs      ExerciseLog[]\n  messages  CampMessage[]\n}\n\n// Consigne d\'un exercice au sein d\'un camp : definie UNIQUEMENT par le createur du camp\n// (la "casquette entraineur"). Tous les membres suivent la meme consigne.\nmodel CampExercise {\n  id             String   @id @default(cuid())\n  campId         String\n  exerciseId     String\n  description    String?  // court descriptif/consigne redige par le createur du camp\n  targetSets     Int      @default(3)\n  targetMode     String   @default("FIXED") // "FIXED" (objectif chiffre) ou "MAX" (a fond, sans cible fixe)\n  targetValue    Int?     // nombre de repetitions OU de secondes vise (voir Exercise.unit) ; inutilise si targetMode = MAX\n  recurrenceType String   @default("DAILY") // "DAILY" | "WEEKLY" | "EVERY_N_DAYS"\n  daysOfWeek     String?  // JSON array ex: "[1,3,5]" (0=dimanche ... 6=samedi), utilise si WEEKLY\n  intervalDays   Int?     // utilise si EVERY_N_DAYS\n  startDate      DateTime @default(now())\n\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise Exercise @relation(fields: [exerciseId], references: [id])\n  logs     ExerciseLog[]\n\n  @@unique([campId, exerciseId])\n}\n\nmodel CampMembership {\n  id       String   @id @default(cuid())\n  userId   String\n  campId   String\n  joinedAt DateTime @default(now())\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campId])\n}\n\nmodel ExerciseLog {\n  id         String   @id @default(cuid())\n  userId     String\n  campId     String\n  exerciseId String\n  date       DateTime // jour concerne (heure normalisee a minuit)\n  setsDone   Int\n  valueDone  Int      // repetitions ou secondes realisees (moyenne/estimation par serie, cf notes)\n  completed  Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp         Camp          @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise     Exercise      @relation(fields: [exerciseId], references: [id])\n  campExercise CampExercise? @relation(fields: [campId, exerciseId], references: [campId, exerciseId])\n\n  @@unique([userId, campId, exerciseId, date])\n}\n\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel UserBadge {\n  id        String   @id @default(cuid())\n  userId    String\n  badgeKey  String   // identifiant du badge, voir src/utils/badges.ts pour le catalogue\n  earnedAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, badgeKey])\n}\n\n// Discussion de groupe entre les membres d\'un camp\nmodel CampMessage {\n  id        String   @id @default(cuid())\n  campId    String\n  userId    String\n  body      String\n  createdAt DateTime @default(now())\n\n  camp Camp @relation(fields: [campId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Message prive entre deux utilisateurs (reserve aux personnes qui partagent au moins un camp)\nmodel DirectMessage {\n  id          String   @id @default(cuid())\n  senderId    String\n  recipientId String\n  body        String\n  createdAt   DateTime @default(now())\n\n  sender    User @relation("MessageSender", fields: [senderId], references: [id], onDelete: Cascade)\n  recipient User @relation("MessageRecipient", fields: [recipientId], references: [id], onDelete: Cascade)\n}\n'
FILES['backend/src/routes/camps.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { generateCampCode } from "../utils/code";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst createCampSchema = z.object({\n  name: z.string().min(1, "Le nom du camp est requis."),\n  description: z.string().max(500).optional().nullable(),\n  exerciseIds: z.array(z.string()).min(1, "Selectionne au moins un exercice."),\n  startDate: z.string().optional().nullable(), // format ISO "YYYY-MM-DD"\n  endDate: z.string().optional().nullable(),\n});\n\n// Cree un camp : choix d\'un ensemble d\'exercices, generation d\'un code d\'invitation.\n// Le createur devient automatiquement membre du camp.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { name, description, exerciseIds, startDate, endDate } = parsed.data;\n\n  if (startDate && endDate && new Date(endDate) < new Date(startDate)) {\n    return res.status(400).json({ error: "La date de fin doit etre apres la date de debut." });\n  }\n\n  // On genere un code unique (tres faible probabilite de collision, on retente si besoin)\n  let code = generateCampCode();\n  for (let attempt = 0; attempt < 5; attempt++) {\n    const clash = await prisma.camp.findUnique({ where: { code } });\n    if (!clash) break;\n    code = generateCampCode();\n  }\n\n  const camp = await prisma.camp.create({\n    data: {\n      name,\n      description: description || null,\n      code,\n      createdById: req.userId!,\n      startDate: startDate ? new Date(startDate) : null,\n      endDate: endDate ? new Date(endDate) : null,\n      exercises: { create: exerciseIds.map((exerciseId) => ({ exerciseId })) },\n      members: { create: [{ userId: req.userId! }] },\n    },\n    include: { exercises: { include: { exercise: true } }, members: true },\n  });\n\n  res.status(201).json(camp);\n});\n\nconst joinSchema = z.object({ code: z.string().min(1) });\n\n// Rejoint un camp existant via son code d\'invitation\nrouter.post("/join", async (req: AuthRequest, res) => {\n  const parsed = joinSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Code requis." });\n  }\n  const code = parsed.data.code.trim().toUpperCase();\n\n  const camp = await prisma.camp.findUnique({ where: { code } });\n  if (!camp) {\n    return res.status(404).json({ error: "Aucun camp ne correspond a ce code." });\n  }\n\n  const existing = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: camp.id } },\n  });\n  if (existing) {\n    return res.status(200).json({ message: "Tu es deja membre de ce camp.", campId: camp.id });\n  }\n\n  await prisma.campMembership.create({ data: { userId: req.userId!, campId: camp.id } });\n  res.status(201).json({ message: `Bienvenue dans le camp "${camp.name}" !`, campId: camp.id });\n});\n\n// Liste les camps dont l\'utilisateur est membre\nrouter.get("/mine", async (req: AuthRequest, res) => {\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    include: {\n      camp: {\n        include: {\n          exercises: { include: { exercise: true } },\n          _count: { select: { members: true } },\n        },\n      },\n    },\n    orderBy: { joinedAt: "desc" },\n  });\n  res.json(memberships.map((m) => m.camp));\n});\n\n// Detail d\'un camp (verifie que l\'utilisateur en est bien membre)\nrouter.get("/:id", async (req: AuthRequest, res) => {\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: req.params.id } },\n  });\n  if (!membership) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: req.params.id },\n    include: {\n      exercises: { include: { exercise: true } },\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  res.json(camp);\n});\n\nconst updateCampSchema = z.object({\n  name: z.string().min(1).optional(),\n  description: z.string().max(500).optional().nullable(),\n});\n\n// Modifie le nom/descriptif d\'un camp : reserve au createur du camp\nrouter.put("/:id", async (req: AuthRequest, res) => {\n  const camp = await prisma.camp.findUnique({ where: { id: req.params.id } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur du camp peut le modifier." });\n  }\n\n  const parsed = updateCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n\n  const updated = await prisma.camp.update({\n    where: { id: req.params.id },\n    data: parsed.data,\n  });\n  res.json(updated);\n});\n\nexport default router;\n'
FILES['frontend/src/components/Layout.tsx'] = 'import { NavLink, useNavigate } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "../context/AuthContext";\n\nconst navItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui" },\n  { to: "/camps", label: "Mes camps" },\n  { to: "/exercices", label: "Exercices" },\n  { to: "/messages", label: "Messages" },\n  { to: "/profil", label: "Profil" },\n];\n\nexport default function Layout({ children }: { children: ReactNode }) {\n  const { user, logout } = useAuth();\n  const navigate = useNavigate();\n\n  return (\n    <div className="min-h-screen flex flex-col md:flex-row">\n      <header className="md:w-64 md:min-h-screen border-b md:border-b-0 md:border-r border-border bg-surface flex md:flex-col justify-between">\n        <div className="p-6">\n          <div className="flex items-center gap-2 mb-8">\n            <span className="w-8 h-8 rounded bg-accent flex items-center justify-center font-display font-bold text-bg text-lg">\n              G\n            </span>\n            <span className="font-display text-lg tracking-wide uppercase">GoTeam</span>\n          </div>\n          <nav className="hidden md:flex md:flex-col gap-1">\n            {navItems.map((item) => (\n              <NavLink\n                key={item.to}\n                to={item.to}\n                className={({ isActive }) =>\n                  `px-3 py-2 rounded-md text-sm font-medium transition-colors ${\n                    isActive ? "bg-accent/15 text-accent" : "text-muted hover:text-text hover:bg-surface2"\n                  }`\n                }\n              >\n                {item.label}\n              </NavLink>\n            ))}\n          </nav>\n        </div>\n        <div className="p-6 hidden md:block">\n          {user && <p className="text-xs text-muted mb-2 truncate">{user.name}</p>}\n          <button\n            onClick={() => {\n              logout();\n              navigate("/connexion");\n            }}\n            className="text-sm text-muted hover:text-accent transition-colors"\n          >\n            Se deconnecter\n          </button>\n        </div>\n      </header>\n\n      <nav className="md:hidden flex justify-around bg-surface border-b border-border order-2">\n        {navItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 text-center py-3 text-xs font-medium ${isActive ? "text-accent" : "text-muted"}`\n            }\n          >\n            {item.label}\n          </NavLink>\n        ))}\n      </nav>\n\n      <main className="flex-1 p-5 md:p-10 max-w-4xl mx-auto w-full">{children}</main>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Progress.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useParams } from "react-router-dom";\nimport { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";\nimport { api } from "../api/client";\nimport StampGrid from "../components/StampGrid";\nimport { computeDueDates } from "../lib/recurrence";\nimport { secondsToMMSS } from "../lib/duration";\nimport type { Program } from "../components/ProgramForm";\n\ninterface ProgressData {\n  program: Program & { startDate: string };\n  history: { date: string; setsDone: number; valueDone: number }[];\n  streak: number;\n  dueCount: number;\n  doneCount: number;\n  regularityRate: number;\n}\n\nexport default function Progress() {\n  const { id: campId, exerciseId } = useParams<{ id: string; exerciseId: string }>();\n  const [data, setData] = useState<ProgressData | null>(null);\n  const [exerciseName, setExerciseName] = useState("");\n  const [unit, setUnit] = useState<"REPS" | "SECONDS">("REPS");\n\n  useEffect(() => {\n    if (!campId || !exerciseId) return;\n    api\n      .get<ProgressData>(`/progress/exercise?campId=${campId}&exerciseId=${exerciseId}`)\n      .then(setData);\n    api.get<{ exercises: { exercise: { id: string; name: string; unit: "REPS" | "SECONDS" } }[] }>(\n      `/camps/${campId}`\n    ).then((camp) => {\n      const exo = camp.exercises.find((e) => e.exercise.id === exerciseId)?.exercise;\n      if (exo) {\n        setExerciseName(exo.name);\n        setUnit(exo.unit);\n      }\n    });\n  }, [campId, exerciseId]);\n\n  if (!data) return <p className="text-muted">Chargement...</p>;\n\n  const completedDates = new Set(data.history.map((h) => h.date));\n  const dueDates = computeDueDates(data.program, 84);\n  const unitLabel = unit === "REPS" ? "repetitions" : "secondes";\n\n  return (\n    <div className="max-w-2xl">\n      <Link to={`/camps/${campId}`} className="text-sm text-muted hover:text-accent">\n        ← Retour au camp\n      </Link>\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mt-2 mb-1">{exerciseName}</h1>\n      <p className="text-muted text-sm mb-6">Ta progression et ta regularite, pas de classement, juste toi.</p>\n\n      <div className="grid grid-cols-3 gap-3 mb-6">\n        <div className="bg-surface border border-border rounded-xl p-4 text-center">\n          <p className="font-display text-3xl text-accent">{data.streak}</p>\n          <p className="text-xs text-muted uppercase tracking-wide mt-1">Jours d\'affilee</p>\n        </div>\n        <div className="bg-surface border border-border rounded-xl p-4 text-center">\n          <p className="font-display text-3xl text-success">{data.regularityRate}%</p>\n          <p className="text-xs text-muted uppercase tracking-wide mt-1">Regularite</p>\n        </div>\n        <div className="bg-surface border border-border rounded-xl p-4 text-center">\n          <p className="font-display text-3xl">\n            {data.doneCount}/{data.dueCount}\n          </p>\n          <p className="text-xs text-muted uppercase tracking-wide mt-1">Seances faites</p>\n        </div>\n      </div>\n\n      <div className="bg-surface border border-border rounded-xl p-5 mb-6">\n        <h2 className="font-display uppercase tracking-wide text-sm mb-3">Carte de pointage (12 dernieres semaines)</h2>\n        <StampGrid completedDates={completedDates} dueDates={dueDates} days={84} />\n        <div className="flex gap-4 mt-3 text-xs text-muted">\n          <span className="flex items-center gap-1">\n            <span className="w-2.5 h-2.5 rounded-sm inline-block stamp-cell done" /> Fait\n          </span>\n          <span className="flex items-center gap-1">\n            <span className="w-2.5 h-2.5 rounded-sm inline-block stamp-cell missed" /> Manque\n          </span>\n          <span className="flex items-center gap-1">\n            <span className="w-2.5 h-2.5 rounded-sm inline-block stamp-cell future" /> Non prevu\n          </span>\n        </div>\n      </div>\n\n      <div className="bg-surface border border-border rounded-xl p-5">\n        <h2 className="font-display uppercase tracking-wide text-sm mb-3">\n          Evolution ({unitLabel} par serie realisees)\n        </h2>\n        {data.history.length === 0 ? (\n          <p className="text-muted text-sm">Pas encore de donnees, valide ta premiere seance dans "Aujourd\'hui".</p>\n        ) : (\n          <div style={{ width: "100%", height: 260 }}>\n            <ResponsiveContainer>\n              <LineChart data={data.history}>\n                <CartesianGrid stroke="#D5E6EA" strokeDasharray="3 3" />\n                <XAxis dataKey="date" stroke="#5C7A81" tick={{ fontSize: 11 }} />\n                <YAxis\n                  stroke="#5C7A81"\n                  tick={{ fontSize: 11 }}\n                  tickFormatter={(v: number) => (unit === "SECONDS" ? secondsToMMSS(v) : String(v))}\n                />\n                <Tooltip\n                  contentStyle={{ backgroundColor: "#FFFFFF", border: "1px solid #D5E6EA", fontSize: 12 }}\n                  labelStyle={{ color: "#152B31" }}\n                  formatter={(v: number) => (unit === "SECONDS" ? secondsToMMSS(v) : v)}\n                />\n                <Line type="monotone" dataKey="valueDone" stroke="#1B8CA3" strokeWidth={2} dot={{ r: 3 }} />\n              </LineChart>\n            </ResponsiveContainer>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CreateCamp.tsx'] = 'import { FormEvent, useState } from "react";\nimport { useNavigate } from "react-router-dom";\nimport { api, ApiError } from "../api/client";\nimport ExercisePicker from "../components/ExercisePicker";\n\nexport default function CreateCamp() {\n  const navigate = useNavigate();\n  const [name, setName] = useState("");\n  const [description, setDescription] = useState("");\n  const [selected, setSelected] = useState<string[]>([]);\n  const [startDate, setStartDate] = useState("");\n  const [endDate, setEndDate] = useState("");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [createdCode, setCreatedCode] = useState<string | null>(null);\n  const [createdId, setCreatedId] = useState<string | null>(null);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    if (selected.length === 0) {\n      setError("Selectionne au moins un exercice.");\n      return;\n    }\n    if (startDate && endDate && endDate < startDate) {\n      setError("La date de fin doit etre apres la date de debut.");\n      return;\n    }\n    setBusy(true);\n    try {\n      const camp = await api.post<{ id: string; code: string }>("/camps", {\n        name,\n        description: description.trim() || null,\n        exerciseIds: selected,\n        startDate: startDate || null,\n        endDate: endDate || null,\n      });\n      setCreatedCode(camp.code);\n      setCreatedId(camp.id);\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de creer le camp.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  if (createdCode && createdId) {\n    return (\n      <div className="max-w-md">\n        <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Camp cree !</h1>\n        <p className="text-muted text-sm mb-6">\n          Partage ce code pour inviter d\'autres personnes a rejoindre "{name}".\n        </p>\n        <div className="bg-surface border-2 border-dashed border-accent rounded-xl p-6 text-center mb-6">\n          <p className="text-xs uppercase tracking-widest text-muted mb-2">Code d\'invitation</p>\n          <p className="font-mono text-4xl tracking-[0.3em] text-accent">{createdCode}</p>\n        </div>\n        <button\n          onClick={() => navigate(`/camps/${createdId}`)}\n          className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2"\n        >\n          Definir les consignes des exercices\n        </button>\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-xl">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Nouveau camp</h1>\n      <p className="text-muted text-sm mb-6">\n        Choisis un nom et les exercices qui feront partie de ce camp. En tant que createur, tu definiras ensuite\n        la consigne (objectif, frequence) suivie par tous les membres.\n      </p>\n\n      <form onSubmit={onSubmit} className="space-y-5">\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="name">\n            Nom du camp\n          </label>\n          <input\n            id="name"\n            required\n            value={name}\n            onChange={(e) => setName(e.target.value)}\n            placeholder="Ex : Preparation pompiers volontaires"\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="description">\n            Descriptif du camp (optionnel)\n          </label>\n          <textarea\n            id="description"\n            value={description}\n            onChange={(e) => setDescription(e.target.value)}\n            placeholder="Ex : Preparation physique pour les tests d\'entree pompiers volontaires..."\n            rows={3}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2 resize-none"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-2">Exercices du camp</label>\n          <ExercisePicker selected={selected} onChange={setSelected} />\n        </div>\n\n        <div className="grid grid-cols-2 gap-4">\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="startDate">\n              Date de debut (optionnel)\n            </label>\n            <input\n              id="startDate"\n              type="date"\n              value={startDate}\n              onChange={(e) => setStartDate(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="endDate">\n              Date de fin (optionnel)\n            </label>\n            <input\n              id="endDate"\n              type="date"\n              value={endDate}\n              onChange={(e) => setEndDate(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n        </div>\n\n        {error && <p className="text-sm text-accent">{error}</p>}\n\n        <button\n          type="submit"\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2 disabled:opacity-60"\n        >\n          {busy ? "Creation..." : "Creer le camp"}\n        </button>\n      </form>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CampDetail.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useParams } from "react-router-dom";\nimport { api } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\nimport ProgramForm, { Program } from "../components/ProgramForm";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface CampExerciseData extends Program {\n  exercise: { id: string; name: string; unit: "REPS" | "SECONDS"; description: string | null };\n}\n\ninterface CampDetailData {\n  id: string;\n  name: string;\n  description: string | null;\n  code: string;\n  createdById: string;\n  startDate: string | null;\n  endDate: string | null;\n  exercises: CampExerciseData[];\n  members: { user: { id: string; name: string } }[];\n}\n\nconst RECURRENCE_LABEL: Record<string, (p: Program) => string> = {\n  DAILY: () => "Tous les jours",\n  WEEKLY: (p) => {\n    const days = p.daysOfWeek ? (JSON.parse(p.daysOfWeek) as number[]) : [];\n    const names = ["Dim", "Lun", "Mar", "Mer", "Jeu", "Ven", "Sam"];\n    return days.map((d) => names[d]).join(", ");\n  },\n  EVERY_N_DAYS: (p) => `Tous les ${p.intervalDays} jours`,\n};\n\nexport default function CampDetail() {\n  const { id } = useParams<{ id: string }>();\n  const { user } = useAuth();\n  const [camp, setCamp] = useState<CampDetailData | null>(null);\n  const [editingExerciseId, setEditingExerciseId] = useState<string | null>(null);\n  const [editingDescription, setEditingDescription] = useState(false);\n  const [descriptionDraft, setDescriptionDraft] = useState("");\n  const [savingDescription, setSavingDescription] = useState(false);\n\n  function load() {\n    if (!id) return;\n    api.get<CampDetailData>(`/camps/${id}`).then(setCamp);\n  }\n  useEffect(load, [id]);\n\n  async function saveDescription() {\n    if (!camp) return;\n    setSavingDescription(true);\n    try {\n      await api.put(`/camps/${camp.id}`, { description: descriptionDraft.trim() || null });\n      setEditingDescription(false);\n      load();\n    } finally {\n      setSavingDescription(false);\n    }\n  }\n\n  if (!camp) return <p className="text-muted">Chargement...</p>;\n\n  const isCoach = user?.id === camp.createdById;\n\n  return (\n    <div className="max-w-2xl">\n      <div className="flex items-start justify-between flex-wrap gap-3 mb-2">\n        <div>\n          <h1 className="font-display text-3xl uppercase tracking-wide">{camp.name}</h1>\n          <p className="text-muted text-sm">\n            {camp.members.length} membre{camp.members.length > 1 ? "s" : ""} :{" "}\n            {camp.members.map((m) => m.user.name).join(", ")}\n          </p>\n          {(camp.startDate || camp.endDate) && (\n            <p className="text-muted text-xs mt-1">\n              {camp.startDate ? `Du ${new Date(camp.startDate).toLocaleDateString("fr-FR")}` : "Sans date de debut"}\n              {camp.endDate ? ` au ${new Date(camp.endDate).toLocaleDateString("fr-FR")}` : ""}\n            </p>\n          )}\n        </div>\n        <div className="bg-surface border border-border rounded-md px-3 py-2 text-center">\n          <p className="text-[10px] uppercase tracking-widest text-muted">Code</p>\n          <p className="font-mono text-lg text-accent">{camp.code}</p>\n        </div>\n      </div>\n\n      <Link\n        to={`/camps/${camp.id}/discussion`}\n        className="inline-block mt-2 text-sm text-accent hover:text-accentSoft"\n      >\n        💬 Discussion du camp\n      </Link>\n\n      <div className="mt-4">\n        {editingDescription ? (\n          <div className="bg-surface2 border border-border rounded-lg p-3">\n            <textarea\n              value={descriptionDraft}\n              onChange={(e) => setDescriptionDraft(e.target.value)}\n              placeholder="Descriptif du camp..."\n              rows={3}\n              className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm resize-none mb-2"\n            />\n            <div className="flex gap-2">\n              <button\n                onClick={saveDescription}\n                disabled={savingDescription}\n                className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm disabled:opacity-60"\n              >\n                {savingDescription ? "Enregistrement..." : "Enregistrer"}\n              </button>\n              <button\n                onClick={() => setEditingDescription(false)}\n                className="text-muted hover:text-text text-sm px-2"\n              >\n                Annuler\n              </button>\n            </div>\n          </div>\n        ) : camp.description ? (\n          <div className="flex items-start justify-between gap-3">\n            <p className="text-sm text-muted italic">{camp.description}</p>\n            {isCoach && (\n              <button\n                onClick={() => {\n                  setDescriptionDraft(camp.description ?? "");\n                  setEditingDescription(true);\n                }}\n                className="text-xs text-accent hover:text-accentSoft shrink-0"\n              >\n                Modifier\n              </button>\n            )}\n          </div>\n        ) : (\n          isCoach && (\n            <button\n              onClick={() => {\n                setDescriptionDraft("");\n                setEditingDescription(true);\n              }}\n              className="text-xs text-accent hover:text-accentSoft"\n            >\n              + Ajouter un descriptif au camp\n            </button>\n          )\n        )}\n      </div>\n\n      <h2 className="font-display uppercase tracking-wide text-lg mt-8 mb-1">Exercices du camp</h2>\n      <p className="text-muted text-sm mb-4">\n        {isCoach\n          ? "En tant que createur du camp, tu definis la consigne (objectif, frequence) suivie par tous les membres."\n          : "Consignes definies par le createur du camp."}\n      </p>\n\n      <div className="space-y-3">\n        {camp.exercises.map((ce) => {\n          const isEditing = editingExerciseId === ce.exercise.id;\n\n          if (isEditing) {\n            return (\n              <ProgramForm\n                key={ce.exercise.id}\n                campId={camp.id}\n                exerciseId={ce.exercise.id}\n                exerciseName={ce.exercise.name}\n                unit={ce.exercise.unit}\n                existing={ce}\n                onSaved={() => {\n                  setEditingExerciseId(null);\n                  load();\n                }}\n                onCancel={() => setEditingExerciseId(null)}\n              />\n            );\n          }\n\n          const unitLabel = ce.exercise.unit === "REPS" ? "reps" : "";\n          const valueLabel =\n            ce.exercise.unit === "SECONDS" && ce.targetValue != null\n              ? secondsToMMSS(ce.targetValue)\n              : `${ce.targetValue} ${unitLabel}`;\n\n          return (\n            <div key={ce.exercise.id} className="bg-surface border border-border rounded-lg p-4">\n              <div className="flex items-center justify-between flex-wrap gap-3">\n                <div>\n                  <p className="font-medium">{ce.exercise.name}</p>\n                  <p className="text-sm text-muted">\n                    {ce.targetMode === "MAX"\n                      ? `${ce.targetSets} serie${ce.targetSets > 1 ? "s" : ""} a fond`\n                      : `${ce.targetSets} x ${valueLabel}`}{" "}\n                    · {RECURRENCE_LABEL[ce.recurrenceType](ce)}\n                  </p>\n                  {ce.description && <p className="text-xs text-muted mt-1 italic">"{ce.description}"</p>}\n                </div>\n                <div className="flex gap-3 items-center shrink-0">\n                  <Link\n                    to={`/camps/${camp.id}/progression/${ce.exercise.id}`}\n                    className="text-sm text-accent hover:text-accentSoft"\n                  >\n                    Progression\n                  </Link>\n                  {isCoach && (\n                    <button\n                      onClick={() => setEditingExerciseId(ce.exercise.id)}\n                      className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                    >\n                      Modifier\n                    </button>\n                  )}\n                </div>\n              </div>\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'

for rel_path, content in FILES.items():
    p = pathlib.Path(rel_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')
    print('OK ->', rel_path)

